/**
 * @brief Copies the contents of a stack from source to destination
 *
 * @param ctx[in] context
 * @param destination[out] destination stack
 * @param source[in] source stack
 */
void lexer_copy_stack(Ctx* ctx,
                      LexerStack* destination,
                      const LexerStack* source) {
  array_reserve(ctx, destination, source->count);
  for (size_t i = 0; i < source->count; i++) {
    destination->data[i] = source->data[i];
  }
  destination->count = source->count;
}

// AI generated by: Zed / GPT-6.1 Sol
// Prompt: "I've came up with a better plan, do not shrink the buffer, just pop
// the tokens which are no longer needed, so that the whole stdin isn't in the
// buffer while not reallocing" Changes: Compact unread input while preserving
// the allocation for reuse.
void lexer_discard_consumed(Ctx* ctx) {
  LexerByteBuffer* buffer = &ctx->lexer.buffer;
  size_t consumed = ctx->lexer.cursor;
  if (consumed == 0)
    return;

  size_t remaining = buffer->count - consumed;
  if (remaining > 0)
    memmove(buffer->data, buffer->data + consumed, remaining);
  buffer->count = remaining;
  ctx->lexer.cursor = 0;
}
